mapper.select:
SELECT BIN_TO_UUID(c.id) AS contentId, c.title AS title FROM contents c JOIN reviews r ON r.content_id = c.id LEFT JOIN content_review_summaries s ON s.content_id = c.id WHERE c.deleted_at IS NULL AND c.review_count >= #{minReviews}
AND c.id > UUID_TO_BIN(#{lastContentId})
GROUP BY c.id, c.title HAVING MAX(s.updated_at) IS NULL OR MAX(r.updated_at) > MAX(s.updated_at) ORDER BY c.id LIMIT #{limit}

SELECT t.contentId AS contentId, t.text AS text, t.rating AS rating FROM ( SELECT BIN_TO_UUID(r.content_id) AS contentId, r.text AS text, r.rating AS rating, ROW_NUMBER() OVER (PARTITION BY r.content_id ORDER BY r.updated_at DESC) AS rn FROM reviews r WHERE r.content_id IN
UUID_TO_BIN(#{contentId})
) t WHERE t.rn <= #{maxReviewsPerContent} ORDER BY t.contentId, t.rn
